exercises.solution:
function mostrarPeso(gramas) {
  return `${(gramas / 1000).toFixed(2)} kg`;
}

test.each([
  [1500, '1.50 kg'],
  [250, '0.25 kg'],
  [2000, '2.00 kg'],
])('mostrarPeso(%i) dá %s', (gramas, esperado) => {
  expect(mostrarPeso(gramas)).toBe(esperado);
});

function ovosSoltos(ovos, porCaixa) {
  return ovos % porCaixa;
}

function avisoDeSobra(ovos, porCaixa) {
  return `Ovos soltos: ${ovosSoltos(ovos, porCaixa)}`;
}

test.each([
  [13, 6, 1],
  [12, 6, 0],
  [30, 12, 6],
])('ovosSoltos(%i, %i) dá %i', (ovos, porCaixa, esperado) => {
  expect(ovosSoltos(ovos, porCaixa)).toBe(esperado);
});

test.each([
  [13, 6, 'Ovos soltos: 1'],
  [12, 6, 'Ovos soltos: 0'],
  [30, 12, 'Ovos soltos: 6'],
])('avisoDeSobra(%i, %i) dá %s', (ovos, porCaixa, esperado) => {
  expect(avisoDeSobra(ovos, porCaixa)).toBe(esperado);
});

